INSERT INTO "business_roles" ("businessId","key","name","permissions","isSystem") SELECT id, 'OWNER', 'Owner', ARRAY['business.view','business.update','pricing.manage','pricing.view','products.view','products.create','products.update','products.delete','inventory.view','inventory.adjust','customers.view','customers.create','customers.update','customers.delete','suppliers.view','suppliers.create','suppliers.update','suppliers.delete','sales.view','sales.create','sales.update','sales.payments','purchases.view','purchases.create','purchases.update','purchases.payments','reports.view','members.view','members.invite','members.update','members.remove','roles.view','roles.manage','audit.view','files.upload','files.view']::TEXT[], true FROM businesses;
