INSERT INTO "business_roles" ("businessId","key","name","permissions","isSystem") SELECT id, 'MEMBER', 'Member', ARRAY['business.view','products.view','inventory.view','customers.view','suppliers.view','sales.view','purchases.view','reports.view','members.view','files.view','members.view']::TEXT[], true FROM businesses;
INSERT INTO "business_roles" ("businessId","key","name","permissions") SELECT DISTINCT bu."businessId", bu."role", bu."role", ARRAY['business.view','products.view','inventory.view','customers.view','suppliers.view','sales.view','purchases.view','reports.view','members.view','files.view']::TEXT[] || CASE WHEN b."membersCanViewPurchasePrice" THEN ARRAY['pricing.view']::TEXT[] ELSE ARRAY[]::TEXT[] END FROM business_users bu JOIN businesses b ON b.id = bu."businessId" ON CONFLICT DO NOTHING;
