CREATE TABLE "business_roles" ("businessId" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "permissions" TEXT[] NOT NULL, "isSystem" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("businessId","key"), FOREIGN KEY ("businessId") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE);
UPDATE business_roles r SET permissions = array_append(r.permissions, 'pricing.view') FROM businesses b WHERE r."businessId" = b.id AND r.key = 'MEMBER' AND b."membersCanViewPurchasePrice" = true;
ALTER TABLE "business_users" ADD CONSTRAINT "business_users_businessId_role_fkey" FOREIGN KEY ("businessId","role") REFERENCES "business_roles"("businessId","key") ON DELETE RESTRICT ON UPDATE CASCADE;
